-- ============================================================
-- 外研社七下 s5 阅读灌库(junior_reading)· publisher='junior_fltrp' · volume='wy7B' · grade=7 · 6 篇 · 每篇5题
-- 幂等:按 (publisher, volume) 先删后插。id/source_key 不预生成。Aaron 跑。
-- ============================================================
BEGIN;

DELETE FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B';

-- 6 篇(不写 id)
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U1', 'The kite my grandpa made', 'When I was seven, my family did not have much money. On my birthday, I hoped for a new toy, but my grandpa gave me an old paper kite. He made it himself with bamboo and some old newspaper. At first I felt a little sad, because my friends had bright new toys. That afternoon, Grandpa took me to a green hill near our home. The wind was strong, and the kite flew high into the blue sky. Grandpa held my hand and we ran together, laughing. The kite looked like a little bird above us. Other children stopped to watch us, and some of them wanted to try, too. We stayed on the green hill until the sun went down. "Money can buy toys," Grandpa said, "but it cannot buy this happy time." I looked at his kind smile and suddenly I understood. That old kite was the best gift of my life. Years later, I still remember that day. Happiness was not in the shops; it was in my grandpa''s warm hands.', '幸福的秘密·一份简单的礼物', 175, 1, '[{"q": "What did Grandpa give the writer for the birthday?", "answer": "B", "options": ["A new toy from the shop.", "An old paper kite he made.", "A big blue bird.", "Some money."], "explanation": "原文\"my grandpa gave me an old paper kite. He made it himself\"。"}, {"q": "Where did Grandpa take the writer to fly the kite?", "answer": "A", "options": ["A green hill near their home.", "A busy shop in town.", "A river far away.", "The school playground."], "explanation": "原文\"took me to a green hill near our home\"。"}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["New toys make children happy.", "Grandpa was very poor.", "Real happiness does not come from money.", "Kites are easy to make."], "explanation": "祖父的话与结尾点题:幸福不来自金钱。"}, {"q": "Why did the writer feel sad at first?", "answer": "D", "options": ["The kite was broken.", "The wind was too strong.", "Grandpa was angry.", "The writer wanted a new toy like the friends had."], "explanation": "\"my friends had bright new toys\",作者也想要新玩具,靠推断。"}, {"q": "In the passage, \"happiness\" means ____.", "answer": "A", "options": ["a warm and joyful feeling", "a kind of new toy", "a strong wind", "a lot of money"], "explanation": "由全文可推断 happiness=幸福、快乐的感觉。"}]'::jsonb, '[{"word": "bamboo", "cn": "竹子"}, {"word": "suddenly", "cn": "突然"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U2', 'The last runner', 'It was the school sports day. In the 800-metre race, a thin boy named Danny ran at the back. Soon everyone else was far ahead. Could he still finish? It looked impossible. Halfway through, Danny''s legs hurt and he wanted to stop. Nobody would blame him if he gave up. But something inside him said, "Keep going." He did not stop. He was so slow that anyone could pass him, yet he never walked. The other runners finished, but Danny still ran, step by step, alone on the track. His face was red, but his eyes were full of hope. One small voice called his name, and soon the whole school joined in. Then something wonderful happened. Everyone in the playground began to cheer for him. "Come on, Danny!" No one laughed; everyone wanted him to finish. At last he crossed the line, tired but proud. He did not win anything, but he learned something important that day: the race is not always about being first. Sometimes finishing is enough.', '坚持·校运会最后一名', 171, 1, '[{"q": "Where did Danny run in the race?", "answer": "A", "options": ["At the back, behind everyone.", "At the very front.", "Beside the teacher.", "Off the track."], "explanation": "原文\"ran at the back\"、\"everyone else was far ahead\"。"}, {"q": "What did the people in the playground do near the end?", "answer": "B", "options": ["They laughed at Danny.", "They cheered for Danny.", "They went home.", "They stopped the race."], "explanation": "原文\"Everyone... began to cheer for him\"。"}, {"q": "What is the best main idea of the passage?", "answer": "C", "options": ["Danny was the fastest runner.", "Sports day is boring.", "Never giving up matters more than winning.", "Running is bad for your legs."], "explanation": "结尾点题:坚持完成比第一更重要。"}, {"q": "Why did everyone start to cheer for Danny?", "answer": "D", "options": ["Because he was winning.", "Because he was funny.", "Because the race was over.", "Because they were moved by his refusal to give up."], "explanation": "他不放弃感动了大家;文中未直说,靠推断。"}, {"q": "\"He never gave up\" — \"gave up\" means ____.", "answer": "A", "options": ["stopped trying", "ran faster", "fell down", "won the race"], "explanation": "由\"wanted to stop... did not stop\"可推断 give up=放弃、停止努力。"}]'::jsonb, '[{"word": "blame", "cn": "责怪"}, {"word": "track", "cn": "跑道"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U3', 'Grandma''s noodles', 'Every winter, my grandma made hot noodles for the whole family. As soon as I opened the door, the kitchen smelled wonderful, and I felt warm at once. The noodles looked simple — just noodles, an egg and some green onions in a big bowl. But they tasted better than any food in a restaurant. Grandma always said, "Good food does not need to be expensive." While we ate, the room grew warm and everyone became happy. My little brother''s face turned red from the hot soup, and we all laughed. Grandma watched us eat and her smile looked so kind. Sometimes she put a little sugar in my bowl, because I liked sweet things. On cold nights, one warm bowl could make my whole body feel happy. Now Grandma is old and cannot cook much, but that taste stays in my heart. When life feels hard, I think of her noodles. They were more than food; they were her love in a bowl. Nothing in the world tastes as sweet as a meal made by someone who loves you.', '食物·奶奶的面条', 180, 1, '[{"q": "What was in Grandma''s bowl of noodles?", "answer": "A", "options": ["Noodles, an egg and some green onions.", "Rice, beef and tofu.", "Bread and milk.", "Fish and potatoes."], "explanation": "原文\"just noodles, an egg and some green onions\"。"}, {"q": "Why did the little brother''s face turn red?", "answer": "B", "options": ["He was angry.", "From the hot soup.", "He ran too fast.", "He felt shy."], "explanation": "原文\"turned red from the hot soup\"。"}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["Noodles are cheap.", "Grandma is a famous cook.", "Simple food made with love is the most precious.", "Winter is the best season."], "explanation": "结尾点题:充满爱的简单食物最珍贵。"}, {"q": "Why does that taste stay in the writer''s heart?", "answer": "D", "options": ["Because the noodles were expensive.", "Because the writer is always hungry.", "Because Grandma taught cooking classes.", "Because the noodles carry Grandma''s love."], "explanation": "\"they were her love in a bowl\",靠推断。"}, {"q": "\"The kitchen smelled wonderful\" — here \"smelled\" is a ____.", "answer": "A", "options": ["linking verb followed by an adjective", "past tense of \"smile\"", "kind of food", "noun"], "explanation": "smell 作系动词后接形容词,是感官系动词。"}]'::jsonb, '[{"word": "onion", "cn": "洋葱,葱"}, {"word": "restaurant", "cn": "餐馆"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U4', 'Study, but play too', 'Last term, my friend Ben studied all the time. Every day after school, he did his homework until late at night. He never played sports and seldom saw his friends. "I must work hard," he always said. But soon Ben looked tired and unhappy, and his marks did not get better. One day our teacher gave him some good advice. "Ben," she said, "work hard, but don''t forget to rest. Play some sport. Meet your friends. A tired mind cannot learn well." Ben decided to try. He began to play basketball twice a week. On weekends, he went out with his friends. At first he worried about losing study time, but something surprising happened. He felt happier, and his mind became clearer. His marks even went up. He slept better at night and woke up happy. He also made new friends when he played, and school felt less boring than before. Now Ben knows the secret: don''t just study all day. Take a break, have some fun, and then go back to your books. Work and play are like two legs — you need both to walk well.', '劳逸结合', 189, 1, '[{"q": "What did Ben do every day after school at first?", "answer": "A", "options": ["Homework until late at night.", "Played basketball.", "Went out with friends.", "Watched TV."], "explanation": "原文\"did his homework until late at night\"。"}, {"q": "How often did Ben play basketball after taking the advice?", "answer": "B", "options": ["Every day.", "Twice a week.", "Once a month.", "Never."], "explanation": "原文\"play basketball twice a week\"。"}, {"q": "What is the best main idea of the passage?", "answer": "C", "options": ["Homework is not important.", "Basketball is the best sport.", "Balancing work and play helps you do better.", "Teachers give too much advice."], "explanation": "结尾点题:劳逸结合让你做得更好。"}, {"q": "Why did Ben''s marks go up after he started to play?", "answer": "D", "options": ["Because he stopped studying.", "Because the tests were easier.", "Because his teacher helped him cheat.", "Because rest made his mind clearer and he learned better."], "explanation": "\"his mind became clearer\"→学得更好;靠推断。"}, {"q": "\"Take a break\" means ____.", "answer": "A", "options": ["stop working for a short rest", "break something", "run away", "study harder"], "explanation": "由上下文\"have some fun, then go back\"可推断 take a break=短暂休息。"}]'::jsonb, '[{"word": "advice", "cn": "建议"}, {"word": "mark", "cn": "分数,成绩"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U5', 'The colours of my village', 'My village is a small place among green hills, and it is the most beautiful place I know. In spring, the hills turn greener than in any other season, and wild flowers open everywhere. The air smells fresh, and the small river runs clearer than glass. Summer is the busiest time. The trees grow taller and thicker, and the fields become a sea of green. It is hotter than spring, but the tall trees give us cool shade. Autumn is my favourite. The leaves turn from green to gold, and the hills look like a big painting. The apples on the trees are the sweetest of the year, and the sky seems higher and bluer. People come to pick the sweet apples, and the whole hill smells fresh and clean. Winter is the quietest season. White snow covers the hills, and the world looks cleaner and brighter than ever. Children run out to play in the snow, and their happy voices fill the cold air. Some people think big cities are more exciting than a small village. But to me, no city in the world is as lovely as my home among the hills. Each season paints my village a different colour, and I love them all.', '家乡的自然色彩', 207, 1, '[{"q": "When do the hills turn greenest?", "answer": "A", "options": ["In spring.", "In summer.", "In autumn.", "In winter."], "explanation": "原文\"In spring, the hills turn greener than in any other season\"。"}, {"q": "What is the writer''s favourite season?", "answer": "B", "options": ["Spring.", "Autumn.", "Summer.", "Winter."], "explanation": "原文\"Autumn is my favourite\"。"}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["Cities are better than villages.", "Winter is too cold.", "The writer loves the changing beauty of the home village.", "Apples grow best in autumn."], "explanation": "全文写家乡四季之美,结尾点题热爱家乡。"}, {"q": "Why does the writer prefer the village to a big city?", "answer": "D", "options": ["Because the village has more shops.", "Because cities are dangerous.", "Because the village is bigger.", "Because to the writer nothing is as lovely as home."], "explanation": "\"no city... is as lovely as my home\",靠推断。"}, {"q": "\"The river runs clearer than glass\" shows the water is very ____.", "answer": "A", "options": ["clean and clear", "dirty", "deep", "cold"], "explanation": "clearer than glass=像玻璃一样清澈,说明水很干净。"}]'::jsonb, '[{"word": "shade", "cn": "树荫"}, {"word": "field", "cn": "田野"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7B', 'U6', 'A trip to the mountains and the sea', 'Last summer, my family took a long trip. In the first week, we went to the mountains in the west. The air up there was as cool as autumn, even in July. Climbing was not as easy as I thought, and by evening I was as tired as I had ever been. But the view from the top was as beautiful as a painting, and I forgot all my tired feelings. In the second week, we drove to the sea in the east. The beach was as bright as gold under the sun, and the water felt as warm as a bath. My little sister was as happy as a bird; she played in the sand all day. We made a small house of sand together, and the sea slowly took it away, but we only laughed. The sea was not as quiet as the mountains, but it was just as lovely. At night, the stars over the sea looked as many as the lights of a big city. The mountains and the sea were very different, yet each was as wonderful as the other. That trip taught me something: the world is as wide as your dreams, so go and see it.', '旅行·山与海', 203, 1, '[{"q": "How did the air in the mountains feel in July?", "answer": "A", "options": ["As cool as autumn.", "As hot as a fire.", "As wet as rain.", "As cold as winter."], "explanation": "原文\"as cool as autumn, even in July\"。"}, {"q": "What did the little sister do at the beach?", "answer": "B", "options": ["Climbed the mountains.", "Played in the sand all day.", "Read a book.", "Slept in the car."], "explanation": "原文\"played in the sand all day\"。"}, {"q": "What is the best main idea of the passage?", "answer": "C", "options": ["Mountains are better than the sea.", "Summer is too hot for trips.", "Both the mountains and the sea were wonderful in their own ways.", "Travelling is always tiring."], "explanation": "结尾点题:山与海各美其美。"}, {"q": "Why did the writer forget the tired feelings at the top?", "answer": "D", "options": ["Because the trip ended.", "Because the sister helped.", "Because it got cold.", "Because the beautiful view made the writer happy."], "explanation": "\"the view... was as beautiful as a painting, and I forgot all my tired feelings\",靠推断。"}, {"q": "\"The world is as wide as your dreams\" encourages readers to ____.", "answer": "A", "options": ["explore widely and dream big", "stay at home", "stop dreaming", "travel less"], "explanation": "由\"go and see it\"可推断:鼓励去广阔世界、勇敢追梦。"}]'::jsonb, '[{"word": "view", "cn": "景色,风景"}, {"word": "climb", "cn": "攀登"}]'::jsonb);

-- 断言
DO $$
DECLARE rn int; q_bad int; orphan int; polluted int;
BEGIN
  SELECT count(*) INTO rn FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B';
  SELECT count(*) INTO q_bad FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B' AND jsonb_array_length(questions)<>5;
  SELECT count(*) INTO orphan FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7B' AND unit IS NULL;
  SELECT count(*) INTO polluted FROM public.junior_reading WHERE volume='wy7B' AND publisher<>'junior_fltrp';
  IF rn<>6 THEN RAISE EXCEPTION 'reading=% 期望6', rn; END IF;
  IF q_bad<>0 THEN RAISE EXCEPTION '题数≠5的篇=%', q_bad; END IF;
  IF orphan<>0 THEN RAISE EXCEPTION 'unit空=%', orphan; END IF;
  IF polluted<>0 THEN RAISE EXCEPTION 'pep_row_polluted=%', polluted; END IF;
  RAISE NOTICE 'OK: % 篇,每篇5题', rn;
END $$;

COMMIT;